import dataclasses
from datetime import datetime
from typing import Dict, Any, Optional

@dataclasses.dataclass
class StoredObject:
    bucket_name: str
    object_name: str
    size: Optional[int] = None
    last_modified: Optional[datetime] = None
    etag: Optional[str] = None
    content_type: Optional[str] = None
    metadata: Optional[Dict[str, Any]] = None

@dataclasses.dataclass
class UploadFileRequest:
    bucket_name: str
    object_name: str
    file_content: bytes
    content_type: Optional[str] = None
    metadata: Optional[Dict[str, Any]] = None

@dataclasses.dataclass
class StorageResponse:
    success: bool
    message: str
    data: Optional[Dict[str, Any]] = None

def normalize_object_name(name: str) -> str:
    """Normalizes an object name for storage, e.g., removing leading/trailing slashes."""
    return name.strip('/')

def parse_s3_metadata(raw_metadata: Dict[str, str]) -> Dict[str, Any]:
    """Parses raw metadata from S3-like services, converting all keys to lowercase."""
    return {k.lower(): v for k, v in raw_metadata.items()}

import os
import boto3

class S3Client:
    def __init__(self, aws_access_key_id: str = None, aws_secret_access_key: str = None, region_name: str = None):
        self.aws_access_key_id = aws_access_key_id or os.environ.get("AWS_ACCESS_KEY_ID")
        self.aws_secret_access_key = aws_secret_access_key or os.environ.get("AWS_SECRET_ACCESS_KEY")
        self.region_name = region_name or os.environ.get("AWS_REGION", "us-east-1")

        if not self.aws_access_key_id or not self.aws_secret_access_key:
            raise ValueError("AWS credentials must be provided or set as environment variables.")

    def get_client(self):
        """
        Returns a configured S3 client.
        """
        return boto3.client(
            "s3",
            aws_access_key_id=self.aws_access_key_id,
            aws_secret_access_key=self.aws_secret_access_key,
            region_name=self.region_name
        )
